contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take parameters: the guess bytes32 and the amount to send when calling lockInGuess.
    // The caller of run must fund this contract sufficiently so it can forward `amount`.
    function run(bytes32 guessHash, uint amount) public payable {
        require(address(this).balance >= amount);
        // Read c's observable state before the call
        uint beforeBalance = address(c).balance;
        // The public getter for mapping guesses is auto-generated as guesses(address) -> (uint block, bytes32 guess)
        (uint beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));

        bool reverted;
        // Make the state-changing call as a top-level statement and capture revert
        try c.lockInGuess{value: amount}(guessHash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterBalance = address(c).balance;
        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));

        // General invariant to hold for every input: If call succeeded then
        // 1) it must have required exactly 1 ether (so contract balance increases by exactly 1 ether),
        // 2) the stored guess must equal the provided guessHash, and
        // 3) the stored block must be nonzero and > current block (we can't know exact block number produced by contract, but it must be nonzero),
        // If the call reverted then the stored guess and block must be unchanged and the contract balance unchanged.
        assert(
            reverted
            ? (afterBalance == beforeBalance && afterBlock == beforeBlock && afterGuess == beforeGuess)
            : (
                // call succeeded
                afterBalance == beforeBalance + 1 ether
                && afterGuess == guessHash
                && afterBlock != 0
            )
        );
    }

    // Allow this test contract to receive ether so it can forward payments to c.
    receive() external payable {}
}

