contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: guessHash and two amounts to fund lockInGuess and the contract's constructor funding (must match C constructor requirement)
    // We cannot call C's constructor here; the checker deploys a fresh C. We only interact via public methods.
    // This run will: optionally call lockInGuess (which may revert), then advance to calling settle (which may revert).
    function run(bytes32 guessHash, uint lockAmount) public payable {
        require(address(this).balance >= lockAmount);

        // Record pre-state: contract balance and stored guess.block for this tester
        uint beforeContractBal = address(c).balance;
        // read public getter for guesses mapping: auto-generated getter has signature guesses(address) returning (uint block, bytes32 guess)
        (uint beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));

        // Attempt to lock in a guess; may revert. Must be a top-level call.
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After attempting lock, read the stored values
        (uint midBlock, bytes32 midGuess) = c.guesses(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt to call settle(); it may revert. Top-level call with try/catch.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Read post-state
        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // If settle succeeded then the stored guess.block for this tester is cleared (== 0)
        // and the contract balance decreased by exactly 2 ether compared to before settle call (i.e. midContractBal - afterContractBal == 2 ether).
        // If settle reverted then either the stored block was already 0 before settle (so no change expected),
        // or the contract balance did not decrease by 2 ether (transfer/require prevented payout).
        assert(
            settleReverted
                ? (
                    // when settle reverted, either there was no active guess to settle (block==0) OR balance unchanged in the sense not decreased by 2 ether
                    midBlock == 0 || (midContractBal - afterContractBal != 2 ether)
                  )
                : (
                    // when settle succeeded, the guess.block must be cleared and contract lost 2 ether
                    afterBlock == 0 && (midContractBal - afterContractBal == 2 ether)
                  )
        );
    }

    // allow receiving Ether for funding lockInGuess
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read internal mapping directly, so we observe only balances and revert flags.
    // Params: guessHash to pass to lockInGuess, lockAmount must be provided to send to lockInGuess (should be 1 ether to succeed)
    function run(bytes32 guessHash, uint lockAmount) public payable {
        // ensure this contract has enough balance to call lockInGuess if the caller chooses so
        require(address(this).balance >= lockAmount);

        // record contract and tester balances before any calls
        uint beforeContractBal = address(c).balance;
        uint beforeSelfBal = address(this).balance;

        // attempt to call lockInGuess; may revert
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // record balances after lock attempt and before settle
        uint midContractBal = address(c).balance;
        uint midSelfBal = address(this).balance;

        // attempt to call settle(); may revert
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // record balances after settle
        uint afterContractBal = address(c).balance;
        uint afterSelfBal = address(this).balance;

        // General rule:
        // If settle succeeded (did not revert) then the contract must have paid out 2 ether to this tester:
        // so contract balance decreased by exactly 2 ether and this tester's balance increased by exactly 2 ether.
        // If settle reverted then either there was no active guess for this tester (so settle reverted due to block==0)
        // OR the contract did not pay out 2 ether (so its balance did not decrease by exactly 2 ether).
        assert(
            settleReverted
                ? (
                    // when settle reverted, it must NOT be the case that the contract lost exactly 2 ether and the tester gained exactly 2 ether
                    !((midContractBal - afterContractBal == 2 ether) && (afterSelfBal - midSelfBal == 2 ether))
                  )
                : (
                    // when settle succeeded, the contract lost exactly 2 ether and tester gained exactly 2 ether
                    (midContractBal - afterContractBal == 2 ether) && (afterSelfBal - midSelfBal == 2 ether)
                  )
        );
    }

    // allow receiving Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params:
    // bytes32 guessHash - the guess to lock in
    // uint lockValue - amount of wei to send when calling lockInGuess (should be 1 ether to succeed)
    // bool doSettle - whether to attempt calling settle after advancing block (we cannot advance blocks deterministically here,
    //                but we still call settle to observe behavior relative to contract rules)
    function run(bytes32 guessHash, uint lockValue, bool doSettle) public payable {
        require(address(this).balance >= lockValue);

        // Record contract balance before any interactions
        uint balBefore = address(c).balance;

        // Attempt to lock in a guess by sending lockValue wei
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Read the public mapping via the auto-generated getter for guesses (struct Guess is not public, but mapping is internal,
        // so there is no direct getter — therefore we can only observe effects via balances and reverts and subsequent behavior.)
        // We will attempt settle if requested and observe whether it pays out incorrectly.

        bool settleReverted = true;
        uint balAfterSettle = address(c).balance;
        uint ourBalAfter = address(this).balance;

        if (doSettle) {
            // try calling settle and capture whether it reverts
            try c.settle() {
                settleReverted = false;
                balAfterSettle = address(c).balance;
                ourBalAfter = address(this).balance;
            } catch {
                settleReverted = true;
                balAfterSettle = address(c).balance;
                ourBalAfter = address(this).balance;
            }
        } else {
            // no settle attempt; values remain as recorded
            balAfterSettle = address(c).balance;
            ourBalAfter = address(this).balance;
        }

        // General invariant to assert:
        // If lockInGuess reverted then no state change should have occurred to c's balance.
        // If lockInGuess succeeded and settle was attempted and did not revert, then either:
        //   - the contract paid out exactly 2 ether (balance decreased by 2 ether and this contract's balance increased by 2 ether),
        //     which can only validly happen when the stored guess matched the computed answer; or
        //   - the contract did not pay out (balance unchanged) if guess didn't match.
        // We cannot observe the guess equality directly; instead we assert that settle never reduces the contract balance
        // unless exactly 2 ether was transferred to this contract in the same transaction.

        // Compute observed balance delta for contract c and for this contract
        uint deltaC;
        if (balAfterSettle >= balBefore) {
            deltaC = balAfterSettle - balBefore;
        } else {
            deltaC = balBefore - balAfterSettle;
        }

        uint deltaUs;
        if (ourBalAfter >= address(this).balance) {
            // this branch should not happen because ourBalAfter was set to current balance; keep simple non-negative
            deltaUs = ourBalAfter - address(this).balance;
        } else {
            deltaUs = address(this).balance - ourBalAfter;
        }

        // Because we cannot directly observe transfers to arbitrary addresses, rely on a weaker but general rule:
        // - If lockInGuess reverted then c balance unchanged.
        // - If lockInGuess succeeded and settle did not revert then either c.balance decreased by exactly 2 ether
        //   and our contract's balance increased by exactly 2 ether, or c.balance did not decrease.

        assert(
            (lockReverted && balAfterSettle == balBefore)
            || (
                !lockReverted && (
                    (!doSettle) || (
                        settleReverted && balAfterSettle == balBefore
                    ) || (
                        !settleReverted && (
                            // either no payout happened
                            balAfterSettle == balBefore
                            // or payout of exactly 2 ether happened from c to this contract
                            || (balBefore >= 2 ether && balBefore - balAfterSettle == 2 ether && ourBalAfter - address(this).balance == 0)
                        )
                    )
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params:
    // bytes32 guessHash - value passed to lockInGuess
    // uint lockAmount - wei to send when calling lockInGuess (caller must fund this contract externally beforehand)
    // bool doSettle - whether to attempt calling settle after lockInGuess
    function run(bytes32 guessHash, uint lockAmount, bool doSettle) public payable {
        require(address(this).balance >= lockAmount);

        // record contract balance before any interactions
        uint balBefore = address(c).balance;

        // Attempt lockInGuess and capture whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // If requested, attempt settle and capture whether it reverted
        bool settleReverted = true;
        if (doSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }

        uint balAfter = address(c).balance;
        uint ourBalAfter = address(this).balance;

        // General invariant:
        // 1) If lockInGuess reverted then c's balance must be unchanged from before the call.
        // 2) If lockInGuess succeeded then any successful settle (if invoked) may either leave c.balance unchanged
        //    or reduce it by exactly 2 ether provided c had at least 2 ether before settle; it must not reduce by some other amount.
        // We express this as a single assert over observed values and revert flags.
        assert(
            // case A: lockInGuess reverted -> contract balance unchanged
            (lockReverted && balAfter == balBefore)
            ||
            // case B: lockInGuess succeeded -> either no successful payout happened, or successful payout was exactly 2 ether
            (
                !lockReverted && (
                    // if we didn't call settle, only requirement is that balance changed only by lockInGuess (which must have increased by lockAmount on success)
                    (!doSettle && balAfter >= balBefore) 
                    ||
                    // if we called settle and it reverted, then c.balance cannot have decreased due to a successful payout in settle
                    (doSettle && settleReverted && balAfter >= balBefore)
                    ||
                    // if settle succeeded, then either no payout (balAfter == balBefore) or payout exactly 2 ether (balBefore - balAfter == 2 ether and balBefore >= 2 ether)
                    (doSettle && !settleReverted && (
                        balAfter == balBefore
                        || (balBefore >= 2 ether && balBefore - balAfter == 2 ether)
                    ))
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params:
    // bytes32 guessHash - passed to lockInGuess
    // uint lockAmount - wei to send with lockInGuess (caller must fund this contract beforehand)
    // bool doSettle - whether to attempt calling settle after lockInGuess
    function run(bytes32 guessHash, uint lockAmount, bool doSettle) public payable {
        require(address(this).balance >= lockAmount);

        // observe balance before any interactions
        uint balBefore = address(c).balance;

        // attempt lockInGuess as a top-level call and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // attempt settle as a top-level call if requested and record whether it reverted
        bool settleCalled = doSettle;
        bool settleReverted = true;
        if (doSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }

        uint balAfter = address(c).balance;

        // General invariant as a single assert:
        // - If lockInGuess reverted then contract balance is unchanged.
        // - If lockInGuess succeeded then contract balance increased by exactly lockAmount.
        //   Additionally, if settle was called and succeeded then either no payout occurred (balance unchanged since lock) or the contract lost exactly 2 ether from its pre-settle balance, which is only allowed when that pre-settle balance was at least 2 ether.
        assert(
            (
                lockReverted && balAfter == balBefore
            ) || (
                !lockReverted && (
                    // after a successful lock, balance must reflect the incoming lockAmount
                    balAfter == balBefore + lockAmount
                ) && (
                    // if settle was not called or it reverted, nothing further is required here
                    (!settleCalled || settleReverted) || (
                        // if settle succeeded, then the effect relative to the balance just before settle must be either 0 or exactly -2 ether
                        (!settleReverted && (
                            // compute pre-settle balance: it must be balBefore + lockAmount
                            // the two allowed outcomes for balAfter are: same as pre-settle, or pre-settle - 2 ether (only if pre-settle >= 2 ether)
                            (balAfter == balBefore + lockAmount) || (
                                (balBefore + lockAmount >= 2 ether && balAfter + 2 ether == balBefore + lockAmount)
                            )
                        ))
                    )
                )
            )
        );
    }

    receive() external payable {}
}

