    // bytes32 guessHash - passed to lockInGuess
    // uint lockAmount - wei to send with lockInGuess
    function run(bytes32 guessHash, uint lockAmount) public payable {
        require(address(this).balance >= lockAmount);

        // balance before attempting lock
        uint balBefore = address(c).balance;

        // try lockInGuess and record revert
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint balAfter = address(c).balance;

        // Now try calling settle immediately; if lock succeeded, settle should revert because it requires block.number > guesses[msg.sender].block.
        // If lock reverted (or never set), settle will also revert because there is no scheduled block. We capture whether settle reverts.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Assert the invariant: either lock reverted leaving balance unchanged and settle reverts,
        // or lock succeeded increasing balance by exactly lockAmount and settle still reverts (since block hasn't advanced yet).
        // This ties observable effects (balance change) to whether lockInGuess succeeded, and ensures settle does not pay out immediately.
        assert(
            (lockReverted && balAfter == balBefore && settleReverted) ||
            (!lockReverted && balAfter == balBefore + lockAmount && settleReverted)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters to drive lockInGuess and settlement timing.
    // senderLockValue must be 1 ether to satisfy lockInGuess; deploy funded c with 1 ether
    // We simulate two-phase interaction: first call lockInGuess with 1 ether, then simulate advancing block by calling settle in same transaction (block.number won't advance but settle requires block.number > guesses.block so we choose a guess block that is less than current block by setting guess block to current block via calling lockInGuess then attempting settle which should revert normally; instead we only assert the invariant for the case where both calls succeed without reverting)
    // Because the checker will explore inputs and can prove the property, we structure the test to observe outcomes and state.

    receive() external payable { }

    function run(bytes32 hash, uint lockAmount) public payable {
        // require we have enough balance to send lockAmount
        require(address(this).balance >= lockAmount);

        // record contract balance before interactions
        uint beforeC = address(c).balance;

        // Try to lock in a guess; record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After attempting lock, attempt to settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Read observable state: contract balance and the public guesses mapping getter for this contract (msg.sender is this contract)
        uint afterC = address(c).balance;
        // The auto-generated getter for guesses returns (uint, bytes32) since struct has two fields
        (uint storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // General rule asserted:
        // If lockInGuess did not revert AND settle did not revert AND beforeC had at least 2 ether (so payout could succeed),
        // then afterC == beforeC - 2 ether AND the storedBlock for this caller is 0 (entry reset).
        // We express the precondition as a logical implication so the assert is general over inputs.
        assert(
            (lockReverted || settleReverted || beforeC < 2 ether) || (afterC == beforeC - 2 ether && storedBlock == 0)
        );
    }
}
